insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-08-11','verbeterd','Dossiers','Dossiers openen sneller',
   'Een dossier bleef soms hangen op het laadscherm omdat er eerst op Bouw7 gewacht werd. De pagina komt nu meteen in beeld; het bedrag aan goedgekeurd meerwerk laadt daarna vanzelf bij. Ook de tabs Financieel, Inkoop, Verkoop en Uren halen hun gegevens sneller op.');
